/* Bristol — source RGB values drawn with CSS hard-stop gradients. */
:root { color-scheme: light; --paper: #fef5f6; }
* { box-sizing: border-box; }
body { margin: 0; background: #f2ecef; color: #47404d; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
.gallery { width: min(100% - 48px, 600px); margin: 36px auto 28px; }
.portrait { margin: 0; }
.artwork-frame { position: relative; width: 100%; aspect-ratio: 600 / 818; container-type: inline-size; overflow: hidden; background: var(--paper); box-shadow: 0 12px 60px #4535470c, 0 1px 3px #45354710; }
.artwork {
  position: absolute;
  width: 600px;
  height: 818px;
  transform-origin: top left;
  transform: scale(tan(atan2(100cqw, 600px)));
  background: var(--paper);
  isolation: isolate;
  contain: strict;
  /* Rasterize the strips together before scaling to avoid seams on mobile. */
  will-change: transform;
}
.paint { position: absolute; inset: 0; pointer-events: none; }
.row { position: absolute; height: 1px; }
figcaption { padding: 20px 2px 0; text-align: right; }
.reference-link { color: #746b7a; font-size: 12px; white-space: nowrap; text-decoration: none; text-underline-offset: 5px; }
.reference-link:hover { color: #393044; text-decoration: underline; }
.reference-link:focus-visible { outline: 2px solid #746b7a; outline-offset: 6px; border-radius: 1px; }
@media (max-width: 540px) {
  .gallery { width: calc(100% - 24px); margin-top: 12px; }
  figcaption { padding: 16px 2px 0; }
}

